fn a(n: u8) -> u32 { match n { 0..=100 => 1, 101.. => 2 } }
fn b(n: i8) -> u32 { match n { ..0 => 1, 0..=127 => 2 } }
fn c(n: u128) -> u32 { match n { 0..=5 => 1, 6.. => 2 } }
fn d(n: i128) -> u32 { match n { ..=-1 => 1, 0.. => 2 } }
fn e(n: i32) -> u32 { match n { i32::MIN..=-1 => 1, 0..=i32::MAX => 2 } }
fn main() { if a(101) == 2 && b(-1) == 1 && c(6) == 2 && d(-1) == 1 && e(0) == 2 { println!("ok"); } }
